"""data/processor.py — Agrégations dérivées depuis les données brutes."""import pandas as pdimport streamlit as st@st.cache_data(show_spinner=False)def compute_flux_heatmap(df_raw: pd.DataFrame) -> pd.DataFrame:    pivot = (        df_raw.groupby(["Pays acheteur","Pays vendeur"])        .size().reset_index(name="Nb transactions")    )    top_buyers  = df_raw["Pays acheteur"].value_counts().head(12).index.tolist()    top_sellers = df_raw["Pays vendeur"].value_counts().head(12).index.tolist()    pivot = pivot[pivot["Pays acheteur"].isin(top_buyers) &                  pivot["Pays vendeur"].isin(top_sellers)]    return pivot.pivot(index="Pays acheteur", columns="Pays vendeur",                       values="Nb transactions").fillna(0)@st.cache_data(show_spinner=False)def get_seller_profile(df_health: pd.DataFrame, seller_id: int) -> dict:    row = df_health[df_health["ID Vendeur"] == seller_id]    return row.iloc[0].to_dict() if not row.empty else {}@st.cache_data(show_spinner=False)def compute_radar_data(df_health: pd.DataFrame, seller_id: int) -> dict:    row = df_health[df_health["ID Vendeur"] == seller_id]    if row.empty:        return {}    r = row.iloc[0]    def norm(val, mn, mx):        return max(0.0, min(1.0, (val - mn) / (mx - mn))) if mx > mn else 0.5    vendor = {        "Note snapshot":    norm(r["Note Snapshot"],       3.0, 5.0),        "Sentiment 6m":     norm(r["Sentiment 6m"],       -1.0, 1.0),        "Momentum":         norm(r["Momentum Sentiment"],  -0.5, 0.5),        "Stabilité":        norm(1 - r["Volatilité 6m"],   0.0, 1.0),        "Récence positive": norm(1 - r["% Avis Nég. 30j"], 0.0, 1.0),    }    market = {        "Note snapshot":    norm(df_health["Note Snapshot"].median(),       3.0, 5.0),        "Sentiment 6m":     norm(df_health["Sentiment 6m"].median(),       -1.0, 1.0),        "Momentum":         norm(df_health["Momentum Sentiment"].median(),  -0.5, 0.5),        "Stabilité":        norm(1 - df_health["Volatilité 6m"].median(),   0.0, 1.0),        "Récence positive": norm(1 - df_health["% Avis Nég. 30j"].median(), 0.0, 1.0),    }    return {"vendor": vendor, "market": market, "axes": list(vendor.keys())}